draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2);
  ctx.bezierCurveTo(W/2 + 100, H/2 - 20, W/2 + 120, H/2 + 20, W/2 + 100, H/2 + 50);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 - 30);
  ctx.lineTo(W/2 - 150, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2);
  ctx.lineTo(W/2 - 100, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2);
  ctx.lineTo(W/2 - 200, H/2);
  ctx.stroke();

  // animate stick figure eating
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2 - 120, H/2 + 20 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
